#!/usr/bin/env python3
"""Draft a portable YT-SQL case from a fallible Python observation.

This is an authoring aid, never a source of normative authority.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import sys
import tempfile
from pathlib import Path

PROJECT = Path(__file__).resolve().parents[1]
SQL_ROOT = PROJECT / "yt-sql"
sys.path.insert(0, str(SQL_ROOT))

from run_python_candidate import observe  # noqa: E402

WARNING = (
    "UNVERIFIED: This expectation was generated by the Python implementation. "
    "Python may contain defects or edge-case errors. Independently review the "
    "query, output types, NULL behaviour and diagnostics before approving it "
    "for the normative YT-SQL corpus."
)


def draft(query: Path, destination: Path, *, case_id: str, dataset: str, order: str) -> None:
    """Write a self-contained candidate outside the authoritative corpus."""
    if not query.is_file() or query.suffix != ".ysql":
        raise ValueError("input must be an existing .ysql file")
    if not case_id.startswith("draft.") or not all(c.islower() or c.isdigit() or c in "._-" for c in case_id):
        raise ValueError("candidate case ID must start with 'draft.' and use lowercase ASCII identifiers")
    if order not in {"ordered", "unordered"}:
        raise ValueError("unsupported ordering mode")
    if destination.exists():
        raise FileExistsError(f"destination already exists: {destination}")
    if destination.resolve().is_relative_to((SQL_ROOT / "cases").resolve()):
        raise ValueError("unreviewed candidates must be written outside the normative cases directory")
    source = query.read_bytes()
    with tempfile.TemporaryDirectory(prefix="ytsql-candidate-") as temporary:
        case = Path(temporary)
        (case / "query.ysql").write_bytes(source)
        manifest = {
            "version": 1,
            "id": case_id,
            "description": "Unverified Python-generated candidate",
            "datasets": [dataset],
            "query": "query.ysql",
            "expected": "expected.json",
            "order": order,
        }
        (case / "test.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
        result = observe(case, root=SQL_ROOT)
        review = {
            "version": 1,
            "status": "unverified",
            "reference_implementation": "python",
            "source_sha256": hashlib.sha256(source).hexdigest(),
            "warning": WARNING,
            "review_required": [
                "syntax and intent",
                "result values and column order",
                "types and coercions",
                "NULL and boundary behaviour",
                "error classification",
            ],
        }
        destination.mkdir(parents=True, exist_ok=False)
        for name in ("query.ysql", "test.json"):
            (destination / name).write_bytes((case / name).read_bytes())
        (destination / "expected.json").write_text(
            json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
        )
        (destination / "REVIEW.json").write_text(
            json.dumps(review, indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
        )
    print(WARNING, file=sys.stderr)
    print(f"Unverified candidate written to {destination}")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, epilog=WARNING)
    parser.add_argument("query", type=Path, help="Existing YT-SQL .ysql query")
    parser.add_argument("destination", type=Path, help="New draft directory OUTSIDE yt-sql/cases")
    parser.add_argument("--id", required=True, help="Draft case ID beginning with draft.")
    parser.add_argument("--dataset", default="python-v6-small")
    parser.add_argument("--order", choices=("ordered", "unordered"), default="ordered")
    args = parser.parse_args()
    try:
        draft(args.query, args.destination, case_id=args.id, dataset=args.dataset, order=args.order)
    except (OSError, ValueError, RuntimeError) as exc:
        print(f"Cannot generate candidate: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
